import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-1: no file under features/profile/ still carries
 * the stale note about adding a workspace parameter to the profile read.
 *
 * This file lives under features/profile/ too, so it scans itself: the
 * searched texts are built from parts and never appear here literally.
 */

const ROOT = process.cwd();
const PROFILE_DIR = join(ROOT, "features", "profile");

const STALE_PHRASE = ["multi", "workspace support"].join("-");
const TASK_MARKER = ["TO", "DO"].join("");
const ORG_ID_PARAM = ["organization", "Id"].join("");

function listFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    return entry.isDirectory() ? listFiles(path) : [path];
  });
}

describe("the profile feature's stale workspace note (profile-todo-cleanup)", () => {
  it("AC-1: no file under features/profile/ mentions the stale phrase or a task note about the organization id parameter", () => {
    const files = listFiles(PROFILE_DIR);
    expect(files.length).toBeGreaterThan(0);

    const withPhrase: string[] = [];
    const withTaskLine: string[] = [];

    for (const file of files) {
      const text = readFileSync(file, "utf8");
      const name = relative(ROOT, file);
      if (text.includes(STALE_PHRASE)) withPhrase.push(name);
      text.split(/\r?\n/).forEach((line, index) => {
        if (line.includes(TASK_MARKER) && line.includes(ORG_ID_PARAM)) {
          withTaskLine.push(`${name}:${index + 1}`);
        }
      });
    }

    expect(withPhrase).toEqual([]);
    expect(withTaskLine).toEqual([]);
  });
});

