 * profile-todo-cleanup — AC-2: the doc comment directly above
 * `getProfileData` states that the profile is per person, so the function
 * takes no organization id.
 */

const SOURCE = join(
  process.cwd(),
  "features",
  "profile",
  "services",
  "get-profile.ts",
);

const DECLARATION =
  "export async function getProfileData(userId: string): Promise<ProfileData>";

function docCommentAbove(source: string, declaration: string): string | null {
  const declarationAt = source.indexOf(declaration);
  if (declarationAt === -1) return null;
  const before = source.slice(0, declarationAt);
  const closeAt = before.lastIndexOf("*/");
  if (closeAt === -1) return null;
  if (before.slice(closeAt + 2).trim() !== "") return null;
  const openAt = before.lastIndexOf("/**", closeAt);
  if (openAt === -1) return null;
  return before.slice(openAt, closeAt + 2);
}

describe("getProfileData's doc comment (profile-todo-cleanup)", () => {
  it("AC-2: the doc comment directly above getProfileData says the profile is per person and takes no organization id", () => {
    const source = readFileSync(SOURCE, "utf8");
    const comment = docCommentAbove(source, DECLARATION);

    expect(comment).not.toBeNull();
    expect(comment).toContain("per person");
    expect(comment).toContain("no organization id");
  });
});

